INSERT INTO Leader_Flavors
SELECT 'LEADER_AZUL_THE_PLAYER', FlavorType, Flavor
FROM Leader_Flavors WHERE LeaderType = 'LEADER_BISMARCK';
UPDATE Leader_Flavors SET Flavor = 10
WHERE LeaderType = 'LEADER_AZUL_THE_PLAYER' AND FlavorType IN ('FLAVOR_RANGED', 'FLAVOR_OFFENSE');
UPDATE Leader_Flavors SET Flavor = 9
WHERE LeaderType = 'LEADER_AZUL_THE_PLAYER' AND FlavorType IN ('FLAVOR_RECON', 'FLAVOR_MOBILE');
UPDATE Leader_Flavors SET Flavor = 8
WHERE LeaderType = 'LEADER_AZUL_THE_PLAYER' AND FlavorType IN ('FLAVOR_DEFENSE', 'FLAVOR_CITY_DEFENSE');
UPDATE Leader_Flavors SET Flavor = 3
WHERE LeaderType = 'LEADER_AZUL_THE_PLAYER' AND FlavorType IN ('FLAVOR_NAVAL', 'FLAVOR_NAVAL_RECON', 'FLAVOR_AIR');

