-- The true Mothership Core is the civilization's Palace replacement. Lua
-- removes it from emergency capitals and restores it only at the recorded
-- founding-capital coordinates.
CREATE TEMP TABLE Azul_MothershipCopy AS
SELECT * FROM Buildings WHERE Type = 'BUILDING_PALACE';
UPDATE Azul_MothershipCopy SET
 ID = NULL,
 Type = 'BUILDING_AZUL_MOTHERSHIP_CORE',
 Description = 'TXT_KEY_BUILDING_AZUL_MOTHERSHIP_CORE',
 Civilopedia = 'TXT_KEY_BUILDING_AZUL_MOTHERSHIP_CORE_PEDIA',
 Strategy = 'TXT_KEY_BUILDING_AZUL_MOTHERSHIP_CORE_STRATEGY',
 Help = 'TXT_KEY_BUILDING_AZUL_MOTHERSHIP_CORE_HELP',
 ExtraCityHitPoints = ExtraCityHitPoints + 50,
 RangedStrikeModifier = RangedStrikeModifier + 15,
 PortraitIndex = 0,
 IconAtlas = 'AZUL_LEADER_ATLAS';
INSERT INTO Buildings SELECT * FROM Azul_MothershipCopy;
DROP TABLE Azul_MothershipCopy;

-- A Buildings row does not carry the Palace's economy or AI priorities. Clone
-- every Palace association present in the live Community Patch database so the
-- Core remains a true Palace replacement before adding Azul's systems.
INSERT INTO Building_YieldChanges
(BuildingType, YieldType, Yield)
