-- Keep a valid but permanently untrainable default behind every internal
-- class. This satisfies Community Patch UI code which dereferences DefaultUnit
-- while preventing civilizations loaded after Azul from inheriting live hulls.
CREATE TEMP TABLE AzulUnitCopy AS SELECT * FROM Units WHERE Type = 'UNIT_BAZOOKA';
UPDATE AzulUnitCopy SET ID=NULL, Type='UNIT_AZUL_INTERNAL_DISABLED',
 Class='UNITCLASS_WARRIOR', Description='TXT_KEY_UNIT_AZUL_INTERNAL_DISABLED',
 Civilopedia=NULL, Strategy=NULL, Help=NULL, Cost=-1, FaithCost=-1,
 PrereqTech=NULL, ObsoleteTech=NULL, ShowInPedia=0, MilitarySupport=0,
 MilitaryProduction=0, PortraitIndex=0, IconAtlas='AZUL_UNIT_ATLAS';
INSERT INTO Units SELECT * FROM AzulUnitCopy;
DROP TABLE AzulUnitCopy;

