-- CanMoveAllTerrain bypasses impassable terrain before the DLL reaches its
-- Ocean/Mountain checks. Opt every live Azul map unit into CanMoveInto so Lua
-- can enforce the Astronomy and Flight gates before that short circuit.
UPDATE Units SET SendCanMoveIntoEvent=1
WHERE Type LIKE 'UNIT_AZUL_FIGHTER_%'
   OR Type LIKE 'UNIT_AZUL_DESTROYER_%'
   OR Type LIKE 'UNIT_AZUL_TESTUDON_%'
   OR Type LIKE 'UNIT_AZUL_TURRET_%'
   OR Type='UNIT_AZUL_FLEET_COMMANDER';

