-- Non-Azul civilizations must not receive the internal era classes. Explicit
-- NULL overrides preserve that restriction while non-NULL class defaults keep
-- Community Patch's production tooltip from indexing GameInfo.Units with nil.
INSERT INTO Civilization_UnitClassOverrides
(CivilizationType, UnitClassType, UnitType)
SELECT Civilization.Type, UnitClass.Type, NULL
FROM Civilizations AS Civilization
CROSS JOIN UnitClasses AS UnitClass
WHERE Civilization.Type <> 'CIVILIZATION_AZUL_BARONIS'
  AND UnitClass.Type LIKE 'UNITCLASS_AZUL_%';

-- Keep Fleet Commander Great-General behavior, including aura and Citadel.
INSERT INTO Unit_FreePromotions
